namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string CategorySlug { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];
    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes = [];
    private int _nextId = 1;

    public RecipeService()
    {
        SeedData();
    }

    public List<Recipe> GetByCategory(string categorySlug)
    {
        return _recipes.Where(r => r.CategorySlug == categorySlug).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(string title, string category, string categorySlug, List<string> ingredients, List<string> steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            CategorySlug = categorySlug,
            Ingredients = ingredients,
            Steps = steps
        });
    }

    public List<(string Name, string Slug)> GetCategories()
    {
        return
        [
            ("Appetizers", "appetizers"),
            ("Main Courses", "main-courses"),
            ("Desserts", "desserts"),
            ("Beverages", "beverages"),
            ("Breads & Baking", "breads"),
            ("Soups & Salads", "soups-salads")
        ];
    }

    private void SeedData()
    {
        AddRecipe("Bruschetta", "Appetizers", "appetizers",
            ["4 slices crusty bread", "2 tomatoes, diced", "Fresh basil", "Olive oil", "Garlic clove", "Salt and pepper"],
            ["Toast bread slices until golden.", "Rub garlic on warm bread.", "Mix tomatoes, basil, oil, salt, and pepper.", "Spoon mixture onto bread and serve."]);

        AddRecipe("Stuffed Mushrooms", "Appetizers", "appetizers",
            ["12 large mushrooms", "1/2 cup cream cheese", "1/4 cup parmesan", "2 cloves garlic, minced", "Fresh parsley"],
            ["Preheat oven to 375°F.", "Remove mushroom stems and hollow caps.", "Mix cream cheese, parmesan, garlic, and parsley.", "Fill caps with mixture.", "Bake 20 minutes until golden."]);

        AddRecipe("Spaghetti Carbonara", "Main Courses", "main-courses",
            ["400g spaghetti", "200g pancetta", "4 egg yolks", "100g pecorino cheese", "Black pepper"],
            ["Cook spaghetti in salted boiling water.", "Fry pancetta until crisp.", "Whisk egg yolks with grated pecorino.", "Toss hot pasta with pancetta.", "Remove from heat, stir in egg mixture.", "Season with black pepper and serve."]);

        AddRecipe("Chicken Tikka Masala", "Main Courses", "main-courses",
            ["500g chicken breast", "1 cup yogurt", "2 tbsp tikka paste", "1 can tomatoes", "1 cup cream", "Basmati rice"],
            ["Marinate chicken in yogurt and tikka paste for 2 hours.", "Grill chicken until charred.", "Simmer tomatoes and cream in a pan.", "Add grilled chicken to sauce.", "Cook 10 minutes.", "Serve over basmati rice."]);

        AddRecipe("Chocolate Lava Cake", "Desserts", "desserts",
            ["200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "50g flour"],
            ["Preheat oven to 425°F.", "Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold chocolate mixture into eggs.", "Add flour gently.", "Pour into greased ramekins.", "Bake 12 minutes — center should be soft.", "Invert onto plates and serve immediately."]);

        AddRecipe("Mango Lassi", "Beverages", "beverages",
            ["1 ripe mango", "1 cup yogurt", "1/2 cup milk", "2 tbsp sugar", "Pinch of cardamom"],
            ["Peel and chop the mango.", "Blend mango, yogurt, milk, sugar, and cardamom.", "Blend until smooth.", "Serve chilled with ice."]);

        AddRecipe("Sourdough Bread", "Breads & Baking", "breads",
            ["500g bread flour", "350g water", "100g sourdough starter", "10g salt"],
            ["Mix flour, water, and starter. Rest 30 minutes.", "Add salt and knead 10 minutes.", "Bulk ferment 4-6 hours with folds every hour.", "Shape and place in banneton.", "Cold proof overnight in fridge.", "Bake in Dutch oven at 450°F for 40 minutes."]);

        AddRecipe("Minestrone Soup", "Soups & Salads", "soups-salads",
            ["2 carrots", "2 celery stalks", "1 zucchini", "1 can white beans", "1 can diced tomatoes", "4 cups vegetable broth", "1 cup pasta"],
            ["Dice all vegetables.", "Sauté carrots and celery in olive oil.", "Add zucchini, beans, tomatoes, and broth.", "Simmer 20 minutes.", "Add pasta and cook until tender.", "Season with salt, pepper, and Italian herbs."]);
    }
}

@page "/categories"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Browse Recipes - RecipeShare</PageTitle>

<h1>Browse Recipes by Category</h1>
<p>Select a category to explore recipes from our community.</p>

<div class="row mt-3">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h5 class="card-title">@category.Name</h5>
                    <a href="categories/@category.Slug" class="btn btn-primary mt-2">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@page "/categories/{Slug}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName - RecipeShare</PageTitle>

<h1>@CategoryName</h1>

@if (Recipes.Count == 0)
{
    <p class="text-muted">No recipes in this category yet. <a href="submit">Submit one!</a></p>
}
else
{
    <div class="row mt-3">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            @if (recipe.AverageRating > 0)
                            {
                                <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.Ratings.Count ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="categories" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string Slug { get; set; } = string.Empty;

    private List<Recipe> Recipes { get; set; } = [];
    private string CategoryName { get; set; } = "Recipes";

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetByCategory(Slug);
        var category = RecipeService.GetCategories().FirstOrDefault(c => c.Slug == Slug);
        CategoryName = category.Name ?? "Recipes";
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@inject RecipeService RecipeService

@if (Recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeShare</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <PageTitle>@Recipe.Title - RecipeShare</PageTitle>

    <h1>@Recipe.Title</h1>
    <p class="text-muted">Category: @Recipe.Category</p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in Recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in Recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <hr />

    <h3>Rate this Recipe</h3>
    <StarRating RecipeId="Recipe.Id" />

    <a href="categories/@Recipe.CategorySlug" class="btn btn-secondary mt-3">← Back to @Recipe.Category</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="d-flex align-items-center gap-2">
    <div class="star-rating" style="font-size: 1.5rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => Rate(star)"
                  @onmouseover="() => HoverStar = star"
                  @onmouseout="() => HoverStar = 0"
                  style="color: @(GetStarColor(star))">
                @(IsStarFilled(star) ? "★" : "☆")
            </span>
        }
    </div>
    @if (Submitted)
    {
        <span class="text-success">Thanks for rating!</span>
    }
</div>

@if (CurrentRecipe is not null && CurrentRecipe.Ratings.Count > 0)
{
    <p class="text-muted mt-1">
        Average: @CurrentRecipe.AverageRating.ToString("F1") / 5
        (@CurrentRecipe.Ratings.Count @(CurrentRecipe.Ratings.Count == 1 ? "rating" : "ratings"))
    </p>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedStar { get; set; }
    private int HoverStar { get; set; }
    private bool Submitted { get; set; }
    private Recipe? CurrentRecipe => RecipeService.GetById(RecipeId);

    private bool IsStarFilled(int star)
    {
        if (HoverStar > 0) return star <= HoverStar;
        if (SelectedStar > 0) return star <= SelectedStar;
        return false;
    }

    private string GetStarColor(int star)
    {
        if (HoverStar > 0 && star <= HoverStar) return "#ffc107";
        if (SelectedStar > 0 && star <= SelectedStar) return "#ffc107";
        return "#6c757d";
    }

    private void Rate(int stars)
    {
        SelectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        Submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (SubmitSuccess)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@Title" has been added.
        <a href="categories/@SelectedCategorySlug">View it in @SelectedCategoryName</a>.
    </div>
}

<EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="SelectedCategorySlug" class="form-select">
            <option value="">-- Select a category --</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat.Slug">@cat.Name</option>
            }
        </InputSelect>
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="IngredientsText" class="form-control" rows="5"
                       placeholder="1 cup flour&#10;2 eggs&#10;1/2 cup sugar" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="StepsText" class="form-control" rows="5"
                       placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." />
    </div>

    <button type="submit" class="btn btn-primary" disabled="@(!IsValid)">Submit Recipe</button>
</EditForm>

@code {
    private string Title { get; set; } = string.Empty;
    private string SelectedCategorySlug { get; set; } = string.Empty;
    private string IngredientsText { get; set; } = string.Empty;
    private string StepsText { get; set; } = string.Empty;
    private bool SubmitSuccess { get; set; }

    private string SelectedCategoryName =>
        RecipeService.GetCategories().FirstOrDefault(c => c.Slug == SelectedCategorySlug).Name ?? "";

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(Title) &&
        !string.IsNullOrWhiteSpace(SelectedCategorySlug) &&
        !string.IsNullOrWhiteSpace(IngredientsText) &&
        !string.IsNullOrWhiteSpace(StepsText);

    private void HandleSubmit()
    {
        if (!IsValid) return;

        var ingredients = IngredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var steps = StepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var categoryName = SelectedCategoryName;

        RecipeService.AddRecipe(Title, categoryName, SelectedCategorySlug, ingredients, steps);
        SubmitSuccess = true;

        // Reset form
        Title = string.Empty;
        IngredientsText = string.Empty;
        StepsText = string.Empty;
    }
}

