    private int HoverStar { get; set; }
    private bool Submitted { get; set; }
    private Recipe? CurrentRecipe => RecipeService.GetById(RecipeId);

    private bool IsStarFilled(int star)
    {
        if (HoverStar > 0) return star <= HoverStar;
        if (SelectedStar > 0) return star <= SelectedStar;
        return false;
    }

    private string GetStarColor(int star)
    {
        if (HoverStar > 0 && star <= HoverStar) return "#ffc107";
        if (SelectedStar > 0 && star <= SelectedStar) return "#ffc107";
        return "#6c757d";
    }

    private void Rate(int stars)
    {
        SelectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        Submitted = true;
    }
